@import "tailwindcss";

/* Porsche Design System Integration Styles */
body {
  font-family: inherit; /* Let Porsche Design System handle typography */
  background-color: rgb(17, 24, 39); /* gray-900 */
  color: white;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1rem;
}

/* Force override all Porsche component styles with maximum specificity */
p-text,
p-text[size="large"],
p-text[size="small"] {
  color: rgb(209, 213, 219) !important; /* gray-300 */
  --p-color-text: rgb(209, 213, 219) !important;
}

p-heading,
p-heading[size="large"],
p-heading[size="medium"],
p-heading[size="small"] {
  color: rgb(96, 165, 250) !important; /* blue-400 */
  --p-color-heading: rgb(96, 165, 250) !important;
}

p-link,
p-link[variant="secondary"],
p-link[variant="primary"] {
  color: rgb(156, 163, 175) !important; /* gray-400 */
  --p-color-link: rgb(156, 163, 175) !important;
}

p-link:hover,
p-link[variant="secondary"]:hover,
p-link[variant="primary"]:hover {
  color: white !important;
  --p-color-link-hover: white !important;
}

p-button,
p-button[variant="primary"] {
  color: white !important;
  background-color: rgb(59, 130, 246) !important; /* blue-500 */
  --p-color-button-text: white !important;
  --p-color-button-background: rgb(59, 130, 246) !important;
}

p-button:hover,
p-button[variant="primary"]:hover {
  background-color: rgb(37, 99, 235) !important; /* blue-600 */
  --p-color-button-background-hover: rgb(37, 99, 235) !important;
}

p-tag,
p-tag[variant="neutral"] {
  color: rgb(17, 24, 39) !important; /* gray-900 */
  background-color: rgb(209, 213, 219) !important; /* gray-300 */
  --p-color-tag-text: rgb(17, 24, 39) !important;
  --p-color-tag-background: rgb(209, 213, 219) !important;
}

/* Wordmark styling with maximum specificity */
p-wordmark,
p-wordmark svg {
  filter: brightness(0) invert(1) !important;
}

/* Override any Porsche Design System CSS variables */
:root {
  --p-color-text: rgb(209, 213, 219) !important;
  --p-color-heading: rgb(96, 165, 250) !important;
  --p-color-link: rgb(156, 163, 175) !important;
  --p-color-link-hover: white !important;
  --p-color-button-text: white !important;
  --p-color-button-background: rgb(59, 130, 246) !important;
  --p-color-button-background-hover: rgb(37, 99, 235) !important;
  --p-color-tag-text: rgb(17, 24, 39) !important;
  --p-color-tag-background: rgb(209, 213, 219) !important;
}

/* Force white text on all elements that might be problematic */
* {
  color: inherit;
}

/* Specific overrides for common Porsche classes */
[class*="p-color-"] {
  color: rgb(209, 213, 219) !important;
}

[class*="p-text-"] {
  color: rgb(209, 213, 219) !important;
}

[class*="p-heading-"] {
  color: rgb(96, 165, 250) !important;
}

/* High contrast mode with even stronger overrides */
@media (prefers-contrast: high) {
  p-text,
  p-text[size="large"],
  p-text[size="small"] {
    color: white !important;
    --p-color-text: white !important;
  }

  p-link,
  p-link[variant="secondary"],
  p-link[variant="primary"] {
    color: rgb(96, 165, 250) !important;
    --p-color-link: rgb(96, 165, 250) !important;
  }

  .text-gray-300,
  .text-gray-400 {
    color: white !important;
  }
}

